/**
 * useViewShortcuts — splat-studio 正交视角快捷键监听（Blender 风格小键盘）
 *
 * 监听 window keydown，按 {@link SHORTCUTS} 码表分发到 editorStore.setCameraMode：
 * - `Numpad7`:          Top（俯视）
 * - `Numpad1`:          Front（正面）
 * - `Numpad3`:          Right（右侧）
 * - `Ctrl+Numpad7`:     Bottom（仰视）
 * - `Ctrl+Numpad1`:     Back（背面）
 * - `Ctrl+Numpad3`:     Left（左侧）
 * - `Numpad5`:          切回 Perspective
 *
 * <!-- @changelog -->
 * <table>
 *   <tr><th>版本</th><th>变更说明</th><th>关联</th></tr>
 *   <tr>
 *     <td>v1.0.0</td>
 *     <td>初始实现：Blender 风格小键盘 Numpad 7/1/3（+Ctrl 反向）+ Numpad 5 切回透视</td>
 *     <td>REQ: 正交视角快捷键</td>
 *   </tr>
 *   <tr>
 *     <td>v1.0.1</td>
 *     <td>
 *       BugFix + DRY 重构：
 *       (1) 添加 if (e.repeat) return 防止长按小键盘时 toggle 语义闪切（与 useTransformShortcuts v1.1.1 相同模式）；
 *       (2) isEditableTarget 提取到 utils/keyboard.ts 共享模块，消除与 useTransformShortcuts 的重复定义
 *     </td>
 *     <td>EVOLVE: Blender 风格 toggle 快捷键在 Web 端必须配 e.repeat 守卫</td>
 *   </tr>
 * </table>
 * <!-- /@changelog -->
 *
 * 设计决策：
 * - 独立于 useTransformShortcuts（视图导航 vs 变换操作，职责不同）
 * - 与 AxesGizmo 点击走同一条 editorStore.setCameraMode 路径
 * - Ctrl 修饰键用于反向视角（Blender 惯例），不与 useTransformShortcuts 的"Ctrl 透传"冲突
 *   （本 handler 仅拦截 Numpad 键，非 Numpad 键仍由 useTransformShortcuts 的 Ctrl 守卫透传）
 * - 可编辑元素守卫复用同一判定逻辑
 *
 * @author v_djlzhou
 */
import { onMounted, onUnmounted } from 'vue'
import { useEditorStore } from '../stores/editor'
import { SHORTCUTS } from '../constants/shortcuts'
import type { CameraMode } from '../types/editor'
import { isEditableTarget } from '../utils/keyboard'

/**
 * 挂载全局正交视角快捷键监听器。
 * 典型用法：在 SplatStudio.vue 的 setup 顶层调用一次。
 */
export function useViewShortcuts(): void {
  const editor = useEditorStore()

  function onKeyDown(e: KeyboardEvent): void {
    // 守卫：可编辑元素
    if (isEditableTarget(e.target)) return
    // 守卫：Alt / Meta 不拦截（Ctrl 在本 handler 中有正当用途：反向视角）
    if (e.altKey || e.metaKey) return
    // 屏蔽 OS 键盘自动重复：toggle 语义（同键再按=切回 Perspective）在 repeat 下会闪切
    if (e.repeat) return

    let mode: CameraMode | null = null

    switch (e.code) {
      case SHORTCUTS.VIEW_TOP:
        // Numpad7: 无 Ctrl → Top, 有 Ctrl → Bottom
        mode = e.ctrlKey ? 'Bottom' : 'Top'
        break
      case SHORTCUTS.VIEW_FRONT:
        // Numpad1: 无 Ctrl → Front, 有 Ctrl → Back
        mode = e.ctrlKey ? 'Back' : 'Front'
        break
      case SHORTCUTS.VIEW_RIGHT:
        // Numpad3: 无 Ctrl → Right, 有 Ctrl → Left
        mode = e.ctrlKey ? 'Left' : 'Right'
        break
      case SHORTCUTS.VIEW_PERSPECTIVE:
        // Numpad5: 切回 Perspective（无论当前在哪个正交视角）
        if (!e.ctrlKey) mode = 'Perspective'
        break
      default:
        return
    }

    if (mode !== null) {
      // toggle 行为：再按同一视角 → 切回 Perspective（与 AxesGizmo 点击行为一致）
      if (editor.cameraMode === mode && mode !== 'Perspective') {
        editor.setCameraMode('Perspective')
      } else {
        editor.setCameraMode(mode)
      }
      e.preventDefault()
    }
  }

  onMounted(() => {
    window.addEventListener('keydown', onKeyDown)
  })

  onUnmounted(() => {
    window.removeEventListener('keydown', onKeyDown)
  })
}
