import type { Command, EditableEntitySnapshot } from '../types/command'
import type { useSceneStore } from '../stores/scene'

/**
 * 删除实体命令。
 *
 * execute：从场景移除实体并清空选中
 * undo：恢复实体并选中
 *
 * 用于：Delete/Backspace 删除、HierarchyPanel 删除按钮、未来右键删除。
 */
export class RemoveEntityCommand implements Command {
  readonly label: string

  constructor(
    private readonly sceneStore: ReturnType<typeof useSceneStore>,
    private readonly entity: EditableEntitySnapshot,
    label?: string,
  ) {
    this.label = label ?? `删除 ${entity.data.id}`
  }

  execute(): boolean {
    if (this.entity.kind === 'floor') {
      return this.sceneStore.removeFloorById(this.entity.data.id) !== null
    }
    return this.sceneStore.removePropById(this.entity.data.id) !== null
  }

  undo(): boolean {
    if (this.entity.kind === 'floor') {
      return this.sceneStore.insertFloorSnapshot(this.entity.data, { select: true })
    }
    return this.sceneStore.insertPropSnapshot(this.entity.data, { select: true })
  }
}
