/**
 * aabb-converters — FloorConfigItem / PropConfigItem → SelectionAABB 转换工具
 *
 * 从 Viewport.vue 抽出，供 PersistentHighlightRenderer 复用，
 * 消除两处各自维护同一逻辑的风险。
 *
 * @changelog
 * | 版本   | 变更说明                                              | 关联               |
 * | v1.0.0 | 从 Viewport.vue 抽出 floorToAABB / propToAABB        | REQ: 大场景标注辅助 |
 * /@changelog
 *
 * @author v_djlzhou
 */
import * as THREE from 'three'
import type { FloorConfigItem, PropConfigItem } from '../../types/scene-config'
import type { SelectionAABB } from '../../stores/scene'

/**
 * 将 FloorConfigItem 转为 SelectionAABB。
 *
 * floor 是平面，画一层贴地薄框（厚度 0.02m），Y 范围与 floor.position.y 对齐。
 * rotationY 从度转弧度（PropConfigItem / FloorConfigItem schema 以度存储）。
 */
export function floorToAABB(floor: FloorConfigItem): SelectionAABB {
  const hw = floor.dimensions.width / 2
  const hd = floor.dimensions.depth / 2
  return {
    minX: floor.position.x - hw,
    maxX: floor.position.x + hw,
    minZ: floor.position.z - hd,
    maxZ: floor.position.z + hd,
    minY: floor.position.y,
    maxY: floor.position.y + 0.02,
    rotationY: THREE.MathUtils.degToRad(floor.rotation?.y ?? 0),
  }
}

/**
 * 将 PropConfigItem 转为 SelectionAABB。
 *
 * 语义约定：
 *   · prop.position.y 是【底面中心】Y（贴地时 y=0），dimensions.y 是物体高度
 *   · v5.0.0：rotationY 直接包含正面方向（faceIndex × 90° 已折算进去），
 *     渲染层蓝色面固定为本地 +Z（face 0）
 */
export function propToAABB(prop: PropConfigItem): SelectionAABB {
  const hw = prop.dimensions.x / 2
  const hd = prop.dimensions.z / 2
  return {
    minX: prop.position.x - hw,
    maxX: prop.position.x + hw,
    minZ: prop.position.z - hd,
    maxZ: prop.position.z + hd,
    minY: prop.position.y,
    maxY: prop.position.y + prop.dimensions.y,
    rotationY: THREE.MathUtils.degToRad(prop.rotation?.y ?? 0),
  }
}
