import * as THREE from 'three'
import type { AxisLock } from '../types/editor'

/**
 * 退化检测阈值：sin(θ) = |forward × axis|，θ 为相机 forward 与世界轴的夹角。
 * 0.08 ≈ sin(4.6°)，小于此视为共线 —— 此时"含轴正对相机的平面"不稳定，
 * 小角度鼠标移动会让射线与平面交点剧烈漂移，直接中断更清爽。
 */
export const MIN_AXIS_SIN_TO_FORWARD = 0.08

/**
 * 复用的临时 buffer 结构。外部调用者持有一份，避免每帧分配。
 *
 * 用法：
 *   const scratch = createAxisProjectionScratch()
 *   buildDragPlane(camera, 'X', worldOrigin, plane, scratch)
 *   ... later in pointermove ...
 *   projectPointerToAxis(camera, domElement, e, plane, axisDir, anchor, scratch)
 */
export interface AxisProjectionScratch {
  readonly ndc: THREE.Vector2
  readonly raycaster: THREE.Raycaster
  readonly camForward: THREE.Vector3
  readonly tmpNormal: THREE.Vector3
  readonly tmpHit: THREE.Vector3
}

export function createAxisProjectionScratch(): AxisProjectionScratch {
  return {
    ndc: new THREE.Vector2(),
    raycaster: new THREE.Raycaster(),
    camForward: new THREE.Vector3(),
    tmpNormal: new THREE.Vector3(),
    tmpHit: new THREE.Vector3(),
  }
}

/**
 * 把 AxisLock（'X' | 'Y' | 'Z'）写入单位向量 out。axis===null 会 throw（调用方责任保证非 null）。
 */
export function writeAxisUnitVector(axis: Exclude<AxisLock, null>, out: THREE.Vector3): THREE.Vector3 {
  out.set(axis === 'X' ? 1 : 0, axis === 'Y' ? 1 : 0, axis === 'Z' ? 1 : 0)
  return out
}

/**
 * 【v1.1.0】从物体的 matrixWorld 抽 local 轴方向（归一化，去除 scale 影响），写入 out。
 *
 * 用途：translate 模式 + transformSpace === 'local' 时，物体本身有旋转，此时沿"物体
 * 本地 X 轴"位移应该是倾斜的世界方向，而不是世界 X 轴。
 *
 * 实现：matrixWorld 的前三列分别是 local X/Y/Z 轴在世界空间的方向（带 scale），
 * 取对应列做归一化即可。
 *
 * @param axis 'X' | 'Y' | 'Z'
 * @param matrixWorld 物体的世界矩阵（通常是 proxyGroup.matrixWorld）
 * @param out 结果写入
 * @returns out（链式调用便利）
 */
export function writeAxisLocalVector(
  axis: Exclude<AxisLock, null>,
  matrixWorld: THREE.Matrix4,
  out: THREE.Vector3,
): THREE.Vector3 {
  const e = matrixWorld.elements
  // 列主序：col0=[e0,e1,e2], col1=[e4,e5,e6], col2=[e8,e9,e10]
  if (axis === 'X') out.set(e[0], e[1], e[2])
  else if (axis === 'Y') out.set(e[4], e[5], e[6])
  else out.set(e[8], e[9], e[10])
  return out.normalize()
}

/**
 * 【v1.1.0】基于已算好的轴方向向量构造拖拽平面。
 *
 * 与 {@link buildDragPlane} 的区别：本函数接收任意世界方向向量（用于 local 坐标系
 * 下的倾斜轴），旧函数接收 `AxisLock` 枚举（仅 world 轴）。
 *
 * @param camera 当前相机
 * @param axisDirWorld 已经归一化的世界方向向量（world 轴 或 local 轴转世界后的方向）
 * @param worldOrigin 平面上一点（通常是物体起始世界位置）
 * @param outPlane 结果写入
 * @param scratch 复用 buffer
 * @returns true 构造成功；false 退化（axisDirWorld 与相机 forward 近乎平行）
 */
export function buildDragPlaneFromDir(
  camera: THREE.Camera,
  axisDirWorld: THREE.Vector3,
  worldOrigin: THREE.Vector3,
  outPlane: THREE.Plane,
  scratch: AxisProjectionScratch,
): boolean {
  // 相机 forward（世界系，已归一化）
  camera.getWorldDirection(scratch.camForward)

  // step1: u = forward × axis
  scratch.tmpNormal.crossVectors(scratch.camForward, axisDirWorld)
  const uLen = scratch.tmpNormal.length()
  if (uLen < MIN_AXIS_SIN_TO_FORWARD) return false
  scratch.tmpNormal.divideScalar(uLen) // 归一化 u

  // step2: n = axis × u（手写叉积，避免新 Vector3 分配）
  const nx = axisDirWorld.y * scratch.tmpNormal.z - axisDirWorld.z * scratch.tmpNormal.y
  const ny = axisDirWorld.z * scratch.tmpNormal.x - axisDirWorld.x * scratch.tmpNormal.z
  const nz = axisDirWorld.x * scratch.tmpNormal.y - axisDirWorld.y * scratch.tmpNormal.x
  scratch.tmpNormal.set(nx, ny, nz).normalize() // 数学上已是单位长度，normalize 防数值误差

  outPlane.setFromNormalAndCoplanarPoint(scratch.tmpNormal, worldOrigin)
  return true
}

/**
 * 构造"含 axis、含 worldOrigin、法向量最贴近 -forward"的拖拽平面（Blender/Maya 标准做法）。
 *
 * 推导 n：希望平面含 axis（允许沿轴滑动），又最正对相机。
 *   forward × axis = u  （u ⊥ forward 且 ⊥ axis）
 *   axis × u       = n  （n ⊥ axis 且是 forward 投到"垂直 axis 的子空间"上的分量反向）
 *   归一化后即为所求。
 *
 * 【v1.1.0 重构】内部转发到 {@link buildDragPlaneFromDir}（保留公共 API 向后兼容）。
 *
 * @param camera 当前相机（必须是 PerspectiveCamera；Ortho 也能工作但本模块未针对优化）
 * @param axis 世界轴（'X' / 'Y' / 'Z'）
 * @param worldOrigin 平面上一点（通常是物体起始世界位置）
 * @param outPlane 结果写入此 Plane（by reference）
 * @param outAxisDir 世界轴单位向量写入此 Vector3（供后续投影复用，避免重算）
 * @param scratch 复用 buffer
 * @returns true 表示构造成功；false 表示退化（axis 与 forward 近乎平行），调用方应中断本次拖拽
 */
export function buildDragPlane(
  camera: THREE.Camera,
  axis: Exclude<AxisLock, null>,
  worldOrigin: THREE.Vector3,
  outPlane: THREE.Plane,
  outAxisDir: THREE.Vector3,
  scratch: AxisProjectionScratch,
): boolean {
  writeAxisUnitVector(axis, outAxisDir)
  return buildDragPlaneFromDir(camera, outAxisDir, worldOrigin, outPlane, scratch)
}

/**
 * 鼠标屏幕坐标（clientX/Y） → 世界射线 → 与 plane 的交点，写入 outHit。
 *
 * @returns true 表示命中；false 表示射线与平面平行或不相交（极端边界）
 */
export function castPointerToPlane(
  camera: THREE.Camera,
  domElement: HTMLElement,
  clientX: number,
  clientY: number,
  plane: THREE.Plane,
  outHit: THREE.Vector3,
  scratch: AxisProjectionScratch,
): boolean {
  const rect = domElement.getBoundingClientRect()
  // NDC：x ∈ [-1,1] 从左到右；y ∈ [-1,1] 从下到上
  scratch.ndc.x = ((clientX - rect.left) / rect.width) * 2 - 1
  scratch.ndc.y = -((clientY - rect.top) / rect.height) * 2 + 1
  scratch.raycaster.setFromCamera(scratch.ndc, camera)
  const hit = scratch.raycaster.ray.intersectPlane(plane, scratch.tmpHit)
  if (!hit) return false
  outHit.copy(hit)
  return true
}

/**
 * 把当前鼠标位置投影到锁定轴上，返回相对 anchor 的世界位移 Δ。
 *
 * 语义：从 anchor（按下时的鼠标平面交点）到"当前鼠标射线与同一平面的交点"，
 * 投影到 axisDir 上（点积）。保证整个拖拽期间"手指始终贴着按下时那个世界点沿轴滑动"。
 *
 * @returns Δworld（米，有符号）；null 表示射线与平面无交（调用方应忽略本帧）
 */
export function projectPointerToAxis(
  camera: THREE.Camera,
  domElement: HTMLElement,
  clientX: number,
  clientY: number,
  plane: THREE.Plane,
  axisDir: THREE.Vector3,
  anchor: THREE.Vector3,
  scratch: AxisProjectionScratch,
): number | null {
  if (!castPointerToPlane(camera, domElement, clientX, clientY, plane, scratch.tmpHit, scratch)) {
    return null
  }
  return (
    (scratch.tmpHit.x - anchor.x) * axisDir.x +
    (scratch.tmpHit.y - anchor.y) * axisDir.y +
    (scratch.tmpHit.z - anchor.z) * axisDir.z
  )
}

/* ==================================================================
 * 【v1.1.0】P2 新增：scale 模式距离比算法所需的辅助函数
 * ================================================================== */

/**
 * 把世界点投影到 CSS 像素坐标系（相对 domElement 左上角）。
 *
 * 用途：scale 模式下算"物体屏幕中心" —— 距离比的基准点。
 *
 * @param camera 当前相机
 * @param worldPoint 要投影的世界点（传 proxyGroup.position）
 * @param domElement 画布 dom（提供 boundingClientRect）
 * @param outScreen 输出 [x, y]（CSS 像素，相对 domElement 左上角）
 * @param scratch 复用 buffer（复用 tmpHit 做 project 临时值）
 * @returns true 命中（点在 near-far 之间）；false 在裁剪平面外
 */
export function projectWorldToScreen(
  camera: THREE.Camera,
  worldPoint: THREE.Vector3,
  domElement: HTMLElement,
  outScreen: { x: number; y: number },
  scratch: AxisProjectionScratch,
): boolean {
  scratch.tmpHit.copy(worldPoint).project(camera)
  // 近/远平面外（裁剪空间 z 不在 [-1, 1]）—— 物体实际不可见，应视为失败
  if (scratch.tmpHit.z < -1 || scratch.tmpHit.z > 1) return false

  const rect = domElement.getBoundingClientRect()
  outScreen.x = ((scratch.tmpHit.x + 1) / 2) * rect.width
  outScreen.y = ((1 - scratch.tmpHit.y) / 2) * rect.height
  return true
}

/**
 * Scale 距离比起始距离的"退化阈值"（CSS 像素）。
 *
 * PRD §2.2 第 5 条：起始距离 < 5px 时退化为线性映射，避免除以小量导致暴冲。
 */
export const SCALE_DIST_START_DEGENERATE_PX = 5

/**
 * 【v1.2.0 → v1.2.1 废弃】Scale 距离比的"起始距离下限"。
 *
 * v1.2.1 已改用 delta 线性模式 `factor = 1 + (distNow - distStart) / SCALE_DELTA_SENSITIVITY_PX`，
 * 不再使用本常量。保留导出以避免下游消费者的破坏性变更。
 *
 * @deprecated v1.2.1 已改用 SCALE_DELTA_SENSITIVITY_PX 的线性模式
 */
export const SCALE_DIST_START_MIN_PX = 200

/**
 * 【v1.2.1 新增 / v1.2.2 调整为 400】Scale delta 线性模式的灵敏度（CSS 像素）。
 *
 * `factor = 1 + (distNow - distStart) / SCALE_DELTA_SENSITIVITY_PX`
 *
 * 拖动 SCALE_DELTA_SENSITIVITY_PX=400 像素 → factor 变化 1：
 *   · 向外拖 400px → factor 从 1 → 2（放大一倍）
 *   · 向内拖 400px → factor 从 1 → 0（缩小到下限，实际由 MIN_DIMENSION clamp）
 *
 * 选值历史：
 *   · v1.2.1 = 200（拖 200px 放大一倍）—— 用户反馈偏敏感
 *   · v1.2.2 = 400（拖 400px 放大一倍）—— 更偏向精细微调手感
 *
 * 参考：Blender 默认 scale gesture 约为"viewport 宽度 1/2 = 2×"（约 300-500px 取决于分辨率），
 * 400 与之接近；CAD 软件（SketchUp/Rhino）多在 200-400 之间。
 */
export const SCALE_DELTA_SENSITIVITY_PX = 400

/**
 * Scale 线性退化模式的分母（CSS 像素）。
 *
 * PRD §2.2 第 5 条：factor = 1 + |mouseDelta| / 100（100px 对应 2× 缩放）。
 */
export const SCALE_LINEAR_FALLBACK_DIVISOR_PX = 100

/**
 * 【v1.1.0 / v1.2.0 / v1.2.1】距离比 scale factor 计算。
 *
 * v1.2.1 delta 线性模式（当前版本）：
 *   factor = 1 + (distNow - distStart) / SCALE_DELTA_SENSITIVITY_PX
 *
 *   · pointerdown 瞬间 distNow == distStart → factor = 1（无跳变，关键性质）
 *   · 向外拖动（distNow > distStart）→ factor > 1 → 放大
 *   · 向内拖动（distNow < distStart）→ factor < 1 → 缩小
 *   · 与按下位置离物体屏幕中心的远近完全解耦，手感全场景一致
 *
 * 退化模式（起始距离 < 5px，鼠标几乎压在屏幕中心按下）：
 *   factor = 1 + |mouseDeltaPx| / SCALE_LINEAR_FALLBACK_DIVISOR_PX
 *   只增不减（保守选择：镜像翻转由调用方的 MIN_DIMENSION clamp 处理，这里不主动缩小）。
 *
 * @param distStart pointerdown 时鼠标到物体屏幕中心的距离（CSS px）
 * @param distNow 当前鼠标到物体屏幕中心的距离（CSS px）
 * @param mouseDeltaPx 当前鼠标到 pointerdown 位置的 CSS 像素距离（退化模式用）
 * @returns factor（无符号，≥0；调用方应配合 MIN_DIMENSION 做下限 clamp）
 */
export function computeScaleFactor(
  distStart: number,
  distNow: number,
  mouseDeltaPx: number,
): number {
  if (distStart < SCALE_DIST_START_DEGENERATE_PX) {
    return 1 + Math.abs(mouseDeltaPx) / SCALE_LINEAR_FALLBACK_DIVISOR_PX
  }
  // delta 线性：保证按下瞬间 factor=1（distNow==distStart），无跳变
  const factor = 1 + (distNow - distStart) / SCALE_DELTA_SENSITIVITY_PX
  // factor 可能为负（向中心拖过头），调用方通过 MIN_DIMENSION clamp 处理
  return factor < 0 ? 0 : factor
}

/* ==================================================================
 * 【v1.3.0】rotate 模式所需辅助函数
 * ================================================================== */

/**
 * 【v1.3.0 迁移自 useTransformProxy.ts】从四元数提取"绕世界 Y 轴的有符号旋转角（弧度）"。
 *
 * 为什么不直接读 `object.rotation.y`：
 *   THREE.Euler 默认 'XYZ' 分解顺序下，当姿态越过 |y|→90° 附近时，
 *   rotation.y 会发生符号反转（万向锁 / 分解歧义），视觉上 Gizmo 匀速转，
 *   但 Euler.y 值会在 ±90° 之间反弹。
 *
 * 本函数直接用 quaternion 算 yaw（atan2 提取），天然单调、天然连续、对万向锁免疫。
 *
 * @param q THREE.Quaternion（通常是 group.quaternion）
 * @returns 绕 Y 轴的 yaw 角（弧度，范围 (-π, π]）
 */
export function getYawFromQuaternion(q: THREE.Quaternion): number {
  const sinyCosp = 2 * (q.w * q.y + q.x * q.z)
  const cosyCosp = 1 - 2 * (q.y * q.y + q.x * q.x)
  return Math.atan2(sinyCosp, cosyCosp)
}
