<script setup lang="ts">
import NumberInput from './NumberInput.vue'

defineProps<{
  x: number
  y: number
  z: number
}>()

const emit = defineEmits<{
  'update:x': [value: number]
  'update:y': [value: number]
  'update:z': [value: number]
}>()
</script>

<template>
  <div class="grid grid-cols-3 gap-1.5">
    <NumberInput :modelValue="x" label="X" color="#ef4444" @update:modelValue="emit('update:x', $event)" />
    <NumberInput :modelValue="y" label="Y" color="#4ade80" @update:modelValue="emit('update:y', $event)" />
    <NumberInput :modelValue="z" label="Z" color="#3b82f6" @update:modelValue="emit('update:z', $event)" />
  </div>
</template>
