import type * as THREE from 'three'
import type { EngineContext, RendererModuleState, CameraModuleState } from '@tencent/viewer-sdk'
import { getModule, rendererModule, cameraModule, collisionModule } from '@tencent/viewer-sdk'

/**
 * 从 EngineContext 一次取到当前 THREE 三件套 + domElement，用于 selection / transform / picker
 * 等交互能力初始化时的一次性快照拉取。
 *
 * ⚠️ 返回结果是 ECS state 的引用，调用方**必须**在使用前 null 守卫；同时**不应**长时间持有
 *    （相机切换 / 渲染器重建时 ECS state 内字段会重新赋值，缓存引用可能失效）。
 *
 * @param ctx EngineContext（可能为 null，未就绪时返回 null 三件套）
 * @returns 三件套快照；任一字段为 null 表示 ECS state 未就绪或该模块未装配
 */
export interface SdkThreeContext {
  scene: THREE.Scene | null
  camera: THREE.PerspectiveCamera | null
  renderer: THREE.WebGLRenderer | null
  domElement: HTMLCanvasElement | null
}

export function getSdkThreeContext(ctx: EngineContext | null): SdkThreeContext {
  const empty: SdkThreeContext = { scene: null, camera: null, renderer: null, domElement: null }
  if (!ctx) return empty

  try {
    const rendererState = getModule<RendererModuleState>(ctx, rendererModule)
    const cameraState = getModule<CameraModuleState>(ctx, cameraModule)
    return {
      scene: rendererState?.scene ?? null,
      camera: cameraState?.camera ?? null,
      renderer: rendererState?.renderer ?? null,
      domElement: rendererState?.renderer?.domElement ?? null,
    }
  } catch {
    return empty
  }
}

/**
 * 便捷单项 getter，用于只需要相机/场景等单一字段的场景（如 Viewport.vue 的 computeFocusCameraState
 * 只需要相机）。内部复用 getSdkThreeContext 的 try/catch 守卫，语义等价。
 *
 * v2.0.0 签名改为 ctx 直传。
 */
export function getSdkCamera(ctx: EngineContext | null): THREE.PerspectiveCamera | null {
  return getSdkThreeContext(ctx).camera
}

export function getSdkScene(ctx: EngineContext | null): THREE.Scene | null {
  return getSdkThreeContext(ctx).scene
}

export function getSdkDomElement(ctx: EngineContext | null): HTMLCanvasElement | null {
  return getSdkThreeContext(ctx).domElement
}

/**
 * FlyCameraController 引用类型别名：从 cameraModule state 取实例类型，避免消费方深挖 SDK 内部路径。
 *
 * 语义：仅 Fly 档存在实例（cameraModule 懒建）；Third/First 档返回 null。
 */
export type SdkFlyCameraController = NonNullable<CameraModuleState['flyController']>

/**
 * 从 EngineContext 取 FlyCameraController（v1.1.0：取代 `sdk.getSceneManager()?.getFlyCameraController()`）。
 *
 * ECS 直读路径：`getModule(ctx, cameraModule).flyController`。语义完全等价，将「ECS 已收编字段的 SDK 层转发」
 * 反模式收敛到 helper。
 *
 * v2.0.0 签名改为 ctx 直传（消费方通过 useEngineContextGetter() 拿 ctx 后传入）。
 *
 * ⚠️ 与 getSdkThreeContext 一样，返回结果是 ECS state 引用，调用方**必须** null 守卫；同时**不应**长时间
 * 持有（切换视角档位 / dispose 时 ECS state.flyController 会置 null，缓存引用可能失效）。
 *
 * @param ctx EngineContext（可能为 null，未就绪时返回 null）
 * @returns FlyCameraController 实例；null 表示未装配 / 未就绪 / 处于角色档
 */
export function getSdkFlyCameraController(ctx: EngineContext | null): SdkFlyCameraController | null {
  if (!ctx) return null

  try {
    return getModule<CameraModuleState>(ctx, cameraModule)?.flyController ?? null
  } catch {
    // launch() 未完成或 camera state 已移除等极端场景
    return null
  }
}

/**
 * 从 EngineContext 取碰撞体网格集合（v1.2.0：取代 `sdk.getSceneManager()?.getCollisionManager()?.getCollisionMeshes()`）。
 *
 * ECS 直读路径：`collisionModule.getCollisionMeshes(ctx)` → 内部 `getModule<CollisionState>(ctx, collisionModule).manager?.getCollisionMeshes() ?? []`。
 * 语义完全等价：manager 未装配（loadCollisionFromConfig 未调用 / 场景无 collision 配置）返回 `[]`，
 * 已装配则返回 CollisionManager 遍历收集的 mesh 列表（含子网格，Legacy / Chunked / Region 三模式共用）。
 *
 * v2.0.0 签名改为 ctx 直传（消费方通过 useEngineContextGetter() 拿 ctx 后传入）。
 *
 * ⚠️ 与其他 helper 一样，返回结果是 ECS state 中 manager 内部持有的 THREE.Object3D[] 引用，
 * 调用方**不应**长时间持有（分块模式下 chunkChanged 会重建列表，缓存引用可能失效或过期）。
 *
 * @param ctx EngineContext（可能为 null，未就绪时返回空数组）
 * @returns 碰撞网格集合；未装配 / 未就绪 / 无 collision 配置 均返回 []
 */
export function getSdkCollisionMeshes(ctx: EngineContext | null): THREE.Object3D[] {
  if (!ctx) return []

  try {
    return collisionModule.getCollisionMeshes(ctx)
  } catch {
    // launch() 未完成或 collision state 已移除等极端场景
    return []
  }
}
